package org.zhixiaoce.aperture;
import android.view.*;
public class SettingsScrollTest{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static KeyEvent down(int n,long t){return new KeyEvent(20,0,n,t);}
 public static void main(String[] a){ok(SettingsScroll.steps(0,10000)==1,"fresh press one step");ok(SettingsScroll.steps(1,699)==1,"initial repeat normal");ok(SettingsScroll.steps(1,700)==2,"700ms accelerates");ok(SettingsScroll.steps(1,1800)==4,"1800ms fast tier");ok(SettingsScroll.steps(6,0)==2&&SettingsScroll.steps(18,0)==4,"repeat fallback when OEM times unavailable");
 RemoteScrollView s=new RemoteScrollView(new android.content.Context(),true);View[] rows=new View[8];for(int i=0;i<8;i++){rows[i]=new View();rows[i].parent=s;if(i>0)rows[i-1].next=rows[i];}rows[0].requestFocus();s.dispatchKeyEvent(down(0,0));ok(s.defaults==1&&View.focused==rows[0],"short press delegated exactly once");s.dispatchKeyEvent(down(6,700));ok(View.focused==rows[2],"repeat moves two rows");s.dispatchKeyEvent(down(18,1800));ok(View.focused==rows[6],"long hold moves four rows");View outside=new View();rows[7].next=outside;s.dispatchKeyEvent(down(20,2000));ok(View.focused==rows[7],"clamped to last descendant");s.dispatchKeyEvent(down(21,2100));ok(View.focused==rows[7]&&s.defaults==1,"held Down does not escape into another surface");s.dispatchKeyEvent(new KeyEvent(20,1,21,2100));ok(s.defaults==2,"key-up remains normal and no timer survives");s.dispatchKeyEvent(new KeyEvent(19,0,20,2000));ok(s.defaults==3,"up never accelerated");RemoteScrollView ordinary=new RemoteScrollView(new android.content.Context());ordinary.dispatchKeyEvent(down(18,2000));ok(ordinary.defaults==1,"cinema/default scroll never accelerated");System.out.println(checks+" production settings speed/focus assertions passed with JVM UI doubles");}
}
